temp_scale<-function()scale_x_continuous(breaks=c(40,50,60),limits=c(40,65),expand=expansion(mult=c(.02,.03)))
melt<-function(x,a,b,pl)(1-pl)*plogis(a/x-b)+pl
# Constrained multistart least squares of the author's sigmoid. No hypothesis test.
fit_melt<-function(x,y){
 objective<-function(par)sum((y-melt(x,exp(par[1]),exp(par[1])/par[2],par[3]))^2)
 fits<-lapply(c(500,1000,2000),function(a)optim(c(log(a),48,.05),objective,method='L-BFGS-B',lower=c(log(10),30,-.1),upper=c(log(20000),90,.95),control=list(factr=1e4,maxit=1500)))
 f<-fits[[which.min(sapply(fits,`[[`,'value'))]];stopifnot(f$convergence==0,is.finite(f$value));c(a=exp(f$par[1]),b=exp(f$par[1])/f$par[2],pl=f$par[3],rss=f$value)
}
# 1. NPARC: 24 fit facets plus a proteome-wide statistic and two phenotype overlays.
n<-read('nparc-NEK2.csv');n$sample_name<-as.character(n$sample_name);alt<-read('nparc-alternative-parameters.csv');alt$group<-as.character(alt$group);nul<-read('nparc-null-parameters.csv')
nf<-fit_melt(n$temperature,n$rel_value);bad_rss<-sum((n$rel_value-melt(n$temperature,nul$a,nul$b,nul$pl))^2)
stopifnot(abs(nf['rss']-nul$rss)<1e-5,bad_rss>10)
cellcols<-setNames(c(teal,blue,coral,violet,gold,'#63A9BD','#9CA550','#CA729C','#608A6B','#B48B63','#7F8DA5','#B68DCE'),sort(unique(n$sample_name)))
grid<-seq(40,65,.1);nullcurves<-expand.grid(temperature=grid,sample_name=names(cellcols));nullcurves$pred<-melt(nullcurves$temperature,nf['a'],nf['b'],nf['pl']);nullcurves$model<-'Null model'
altcurves<-merge(expand.grid(temperature=grid,group=names(cellcols)),alt,by='group');altcurves$pred<-melt(altcurves$temperature,altcurves$a,altcurves$b,altcurves$pl);altcurves<-transmute(altcurves,temperature,sample_name=group,pred,model='Alternative model')
nd<-n;nd$pred<-melt(nd$temperature,nf['a'],nf['b'],nf['pl']);nd$model<-'Null model'
ad<-merge(n,alt,by.x='sample_name',by.y='group');ad$pred<-melt(ad$temperature,ad$a,ad$b,ad$pl);ad<-transmute(ad,sample_name,temperature,rel_value,pred,model='Alternative model')
fitted<-bind_rows(select(nd,sample_name,temperature,rel_value,pred,model),ad);curves<-bind_rows(nullcurves,altcurves)
modelplot<-function(m,tag){
 dd<-filter(fitted,model==m);cc<-filter(curves,model==m);rss<-sum((dd$rel_value-dd$pred)^2)
 ggplot(dd,aes(temperature,rel_value))+geom_segment(aes(xend=temperature,yend=pred),colour='#A2AAB1',linewidth=.25,linetype=2)+geom_line(data=cc,aes(y=pred,colour=sample_name),linewidth=.45)+geom_point(aes(colour=sample_name),size=1.1)+facet_wrap(~sample_name,ncol=6,labeller=labeller(sample_name=function(x)gsub('_','-',x)))+scale_colour_manual(values=cellcols)+temp_scale()+scale_y_continuous(breaks=c(0,.5,1),limits=c(-.025,1.06))+labs(x='Temperature (°C)',y='Fraction non-denatured',title=sprintf('NEK2_0  ·  %s  ·  RSS = %.4f',m,rss),tag=tag)+theme(legend.position='none')
}
v<-read('nparc-global.csv');v$effect<-v$rss-v$rssAlternative;v$highlight<-v$F_statistic>=quantile(v$F_statistic,.9);stopifnot(all(v$effect>0));labs<-filter(v,id%in%c('NEK2_0','DNTT_1','INPP4B_1','TP53_1','FBP1_1'))
vg<-ggplot(v,aes(effect,F_statistic))+geom_point(colour='#C7CED5',alpha=.28,size=.45)+geom_point(data=filter(v,highlight),colour=teal,alpha=.6,size=.55)+geom_point(data=labs,colour=coral,size=1.5)+geom_text_repel(data=labs,aes(label=id),size=7/2.845276,seed=19,box.padding=.4,min.segment.length=0,segment.size=.2,max.overlaps=Inf,colour=ink)+scale_x_log10(breaks=c(.1,1,10))+coord_cartesian(xlim=c(.05,17.5),clip='off')+labs(x='RSS(null) − RSS(alternative)',y='F-statistic',title='Proteome-wide differences',tag='b')
fitdata<-function(df){out<-list();par<-list();for(s in unique(df$sample_name)){z<-df[df$sample_name==s,];f<-fit_melt(z$temperature,z$rel_value);out[[s]]<-data.frame(sample_name=s,temperature=grid,pred=melt(grid,f['a'],f['b'],f['pl']));par[[s]]<-data.frame(sample_name=s,t(f))};list(curves=bind_rows(out),parameters=bind_rows(par))}
dnt<-read('nparc-DNTT.csv');dnt$stage<-factor(ifelse(grepl('other',dnt$state),'Other',ifelse(dnt$state=='pre.pro.B','Pre-pro-B',ifelse(dnt$state=='pro.B','Pro-B','Pre-B'))),levels=c('Pre-pro-B','Pro-B','Pre-B','Other'));stopifnot(!anyNA(dnt$stage));dfit<-fitdata(dnt);dc<-left_join(dfit$curves,distinct(dnt,sample_name,stage),by='sample_name');stagecols<-c('Pre-pro-B'=blue,'Pro-B'=gold,'Pre-B'=violet,'Other'='#B6BDC4')
dg<-ggplot(dnt,aes(temperature,rel_value,colour=stage,group=sample_name))+geom_line(data=dc,aes(y=pred),linewidth=.45)+geom_point(size=.8,alpha=.8)+scale_colour_manual(values=stagecols,drop=FALSE)+temp_scale()+labs(x='Temperature (°C)',y='Fraction non-denatured',title='DNTT_1',tag='c',colour=NULL)+guides(colour=guide_legend(nrow=2,byrow=TRUE,override.aes=list(size=1.2)))+theme(legend.position='bottom')
inp<-read('nparc-INPP4B.csv');inp$subtype<-ifelse(inp$subtype=='TCF3.PBX1','TCF3-PBX1','Other');ifit<-fitdata(inp);ic<-left_join(ifit$curves,distinct(inp,sample_name,subtype),by='sample_name')
ig<-ggplot(inp,aes(temperature,rel_value,colour=subtype,group=sample_name))+geom_line(data=ic,aes(y=pred),linewidth=.45)+geom_point(size=.8)+scale_colour_manual(values=c('TCF3-PBX1'=coral,'Other'='#B6BDC4'))+temp_scale()+labs(x='Temperature (°C)',y='Fraction non-denatured',title='INPP4B_1',tag='d',colour=NULL)+theme(legend.position='bottom')
p<-modelplot('Null model','a')/modelplot('Alternative model',NULL)/(vg+dg+ig+plot_layout(widths=c(1.15,1,1)))+plot_layout(heights=c(1,1,1.32))
files<-c(export(fitted,'nparc','fit_observations'),export(curves,'nparc','model_curves'),export(v,'nparc','global'),export(dnt,'nparc','DNTT'),export(dc,'nparc','DNTT_curves'),export(inp,'nparc','INPP4B'),export(ic,'nparc','INPP4B_curves'),export(dfit$parameters,'nparc','DNTT_fit_parameters'),export(ifit$parameters,'nparc','INPP4B_fit_parameters'))
finish('nparc',p,files,'Source Fig4a-d numeric panels. Author sigmoid retained. Stored NEK2 null a=10.241 is inconsistent with stored RSS; refit all96 observations, reproducing RSS to1e-5. Alternative parameters used unchanged. DNTT/INPP4B curves locally refit with constrained multistart least squares; global F-statistics retained, not recomputed. Top-decile highlight uses >=90th percentile. No schematic mechanisms or new significance tests.',list(proteoforms=nrow(v),NEK2_observations=nrow(n),cell_lines=12,null_rss=unname(nf['rss']),stored_null_rss=nul$rss,invalid_stored_parameter_rss=bad_rss,alternative_rss=sum((ad$rel_value-ad$pred)^2)),as.list(c(cellcols,stagecols)),183,200)
