v<-read('coaggregation-global.csv');v$effect<-v$max_rss-v$min_rss;v$highlight<-v$f_stat>quantile(v$f_stat,.9);lab<-filter(v,pair%in%c('CXXC1_2:SETD1A_3','POLR3A_1:POLR3B_3','EXOC2_3:EXOC4_3','PSMA3_2:PSMA7_1','EIF3F_2:EIF3I_1','MDM2_2:TP53_1'))
