bg<-ggplot(sen,aes(status,sDSS,fill=status))+geom_boxplot(width=.5,coef=Inf,colour=ink,linewidth=.35,alpha=.35,outlier.shape=NA)+geom_point(aes(colour=status),position=position_jitter(width=.1,seed=291029),size=1.4)+facet_wrap(~drug_name,ncol=2)+scale_fill_manual(values=c('Differential'=coral,'Co-aggregating'=teal))+scale_colour_manual(values=c('Differential'=coral,'Co-aggregating'=teal))+scale_x_discrete(labels=c('Differential'='Diff.','Co-aggregating'='Co-agg.'))+labs(x=NULL,y='Drug sensitivity (sDSS)',tag='e')+theme(legend.position='none')
