# 3. Metabolomics: full feature distributions and identification-retention curves.
mode_names<-c('C18 ESI+','C18 ESI−','HILIC ESI+','HILIC ESI−');ds<-bind_rows(lapply(1:4,function(i){x<-read(paste0('dilution-7',letters[i],'.csv'));x$mode<-mode_names[i];x}))
ds$cors<-abs(ds$cors);ds$mode<-factor(ds$mode,levels=mode_names);ds$Tools<-factor(ds$Tools,levels=c('MetaboAnalyst','XCMS','MSDIAL','MzMine'));stopifnot(!anyNA(ds$Tools),!anyNA(ds$mode),all(ds$cors<=1,na.rm=TRUE));tc<-c(MetaboAnalyst=teal,XCMS=blue,MSDIAL=violet,MzMine=coral)
# Source ylim removes values below0.3 BEFORE density/mean/sd; retain full and displayed tables separately.
dd<-filter(ds,cors>=.3,cors<=1.1);summ<-dd%>%group_by(mode,Tools)%>%summarise(n=n(),mean=mean(cors),sd=sd(cors),.groups='drop');bins<-dd%>%mutate(bin=floor(cors/.004)*.004+.002)%>%count(mode,Tools,bin,name='count')
vp<-ggplot(dd,aes(Tools,cors,fill=Tools))+geom_violin(trim=TRUE,linewidth=.35,colour=ink,alpha=.5,scale='width')+geom_point(data=bins,aes(y=bin,size=count),colour=ink,alpha=.55,show.legend=FALSE)+geom_errorbar(data=summ,aes(y=mean,ymin=mean-sd,ymax=mean+sd),width=.15,colour=ink,linewidth=.4)+geom_point(data=summ,aes(y=mean),shape=21,fill='white',size=1.7,stroke=.4)+facet_wrap(~mode,ncol=2)+scale_fill_manual(values=tc)+scale_size_area(max_size=1.4)+scale_x_discrete(labels=c(MetaboAnalyst='MetaboAnalystR',MSDIAL='MS-DIAL',MzMine='MZmine'))+scale_y_continuous(breaks=c(.4,.6,.8,1))+coord_cartesian(ylim=c(.3,1.12))+labs(x=NULL,y='Absolute correlation |r|',tag='a')+theme(legend.position='none',panel.grid.major.y=element_line(colour='#E5E9ED',linewidth=.22),axis.text.x=element_text(angle=20,hjust=1))
cu<-bind_rows(lapply(1:2,function(i){x<-read(paste0('dilution-9',letters[i],'.csv'));x$mode<-c('DDA','SWATH-DIA')[i];x}));cu$Tools<-gsub('MSDIAL/MSFinder','MS-DIAL/MS-Finder',cu$Tools,fixed=TRUE);cu$Tools<-gsub('MzMine/SIRIUS','MZmine/SIRIUS',cu$Tools,fixed=TRUE);cu$Tools<-gsub('MetaboAnalyst','MetaboAnalystR',cu$Tools,fixed=TRUE)
ct<-c('MetaboAnalystR'=teal,'MS-DIAL/MS-Finder'=violet,'MZmine/SIRIUS'=coral,'XCMS/SIRIUS'=blue)
cp<-ggplot(cu,aes(Cors_r,Compound_num,colour=Tools))+geom_line(linewidth=.65)+geom_point(size=.55)+facet_wrap(~mode,ncol=2,scales='free_y')+scale_colour_manual(values=ct)+scale_x_reverse(breaks=seq(0,1,.2))+labs(x='Minimum absolute correlation |r|',y='Identified compounds',colour=NULL,tag='b')+theme(legend.position='bottom',panel.grid.major.y=element_line(colour='#E5E9ED',linewidth=.22))+guides(colour=guide_legend(nrow=2,byrow=TRUE))
p<-vp/cp+plot_layout(heights=c(1.65,1))
files<-c(export(ds,'dilution','all_features'),export(dd,'dilution','displayed_features'),export(summ,'dilution','summaries'),export(bins,'dilution','binned_marks'),export(cu,'dilution','identified_counts'))
finish('dilution',p,files,'Supplementary Fig7a-d plus9a-b. Source absolute correlations; author ylim0.3..1.1 filters before mean±SD/density, retained exactly and full values exported. Dense point column uses deterministic0.004 bins with area proportional to count instead of stacking128k dots. Lower curves preserve all51 thresholds perworkflow and reversed x-axis; DDA/DIA free yscales. Counts are source summed mode-specific identifications, not guaranteed distinct compound identities. No new rawLCMS processing.',list(full_features=nrow(ds),displayed_features=nrow(dd),below_source_display=sum(ds$cors<.3,na.rm=TRUE),missing_correlations=sum(is.na(ds$cors)),identification_rows=nrow(cu)),as.list(ct),183,174)
# 4. SIMPEL: corrected isotopologues, pool-adjusted label trajectories and clustering.
mid<-read('isotope-mid.csv');en<-read('isotope-enrichment.csv');mm<-filter(mid,compound=='PC(36:4)');mm$isotopologue<-factor(mm$isotopologue,levels=paste0('M',0:27));stopifnot(!anyNA(mm));ms<-mm%>%group_by(isotopologue,time)%>%summarise(mean=mean(value),se=sd(value)/sqrt(n()),.groups='drop');iso_colors<-setNames(c(ink,colorRampPalette(c(blue,teal,'#A6C86B',gold,coral,violet))(27)),paste0('M',0:27))
ms$isotope_count<-as.integer(sub('M','',ms$isotopologue));ms$view<-factor(ifelse(ms$isotope_count==0,'M0','M1–M27'),levels=c('M0','M1–M27'))
mp<-ggplot(ms,aes(time,mean,group=isotopologue))+geom_line(data=filter(ms,isotope_count==0),colour=ink,linewidth=.6)+geom_point(data=filter(ms,isotope_count==0),colour=ink,size=1)+geom_line(data=filter(ms,isotope_count>0),aes(colour=isotope_count),linewidth=.45)+geom_point(data=filter(ms,isotope_count>0),aes(colour=isotope_count),size=.7)+geom_errorbar(aes(ymin=mean-se,ymax=mean+se),width=.5,linewidth=.2,alpha=.5)+facet_wrap(~view,scales='free_y',ncol=2)+scale_colour_gradientn(colours=c(blue,teal,'#A6C86B',gold,coral,violet),limits=c(1,27),breaks=c(1,7,14,21,27),labels=paste0('M',c(1,7,14,21,27)))+scale_x_continuous(breaks=c(0,16,32))+labs(x='13C supply (h)',y='Mass isotopologue fraction',title='PC(36:4) · Natural-abundance corrected',tag='a',colour=NULL)+guides(colour=guide_colourbar(barwidth=unit(52,'mm'),barheight=unit(2,'mm'),ticks=FALSE))+theme(legend.position='bottom')

e<-en%>%group_by(compound,time)%>%summarise(mean=mean(value),sd=sd(value),se=sd(value)/sqrt(n()),.groups='drop')
ep<-ggplot(filter(e,compound=='PC(36:4)'),aes(time,mean))+geom_line(colour=teal,linewidth=.65)+geom_errorbar(aes(ymin=mean-se,ymax=mean+se),colour=teal,width=.7,linewidth=.35)+geom_point(shape=21,fill=teal,size=2,colour=ink,stroke=.3)+scale_x_continuous(breaks=c(0,8,16,32))+labs(x='13C supply (h)',y='13C product formed (nmol)',title='PC(36:4) · Pool-adjusted labeling',tag='b')
wide<-en%>%mutate(col=paste(time,replicate,sep='_'))%>%select(compound,col,value)%>%pivot_wider(names_from=col,values_from=value);mat<-as.matrix(wide[,-1]);rownames(mat)<-wide$compound;stopifnot(!anyNA(mat),nrow(mat)==16)
# Source release uses25starts; deterministic Hartigan-Wong substitutes for current kmeans++ dependency.
set.seed(291029);km<-kmeans(mat,centers=3,nstart=25,iter.max=100);ord<-order(tapply(e$mean[e$time==32],km$cluster[match(e$compound[e$time==32],rownames(mat))],mean),decreasing=TRUE);map<-setNames(seq_along(ord),ord);cl<-data.frame(compound=rownames(mat),cluster=factor(map[as.character(km$cluster)],levels=1:3));e<-left_join(e,cl,by='compound');cs<-NULL
# Explicitly compute between-lipid SD, not SD of a just-overwritten scalar.
cs<-e%>%group_by(cluster,time)%>%summarise(cluster_mean=mean(mean),cluster_sd=sd(mean),.groups='drop')%>%rename(mean=cluster_mean,sd=cluster_sd)
clcols<-c('1'=teal,'2'=coral,'3'=blue)
cg<-ggplot(cs,aes(time,mean,colour=cluster,fill=cluster))+geom_ribbon(aes(ymin=mean-sd,ymax=mean+sd),alpha=.16,colour=NA)+geom_line(linewidth=.7)+geom_point(size=.9)+scale_colour_manual(values=clcols)+scale_fill_manual(values=clcols)+scale_x_continuous(breaks=c(0,8,16,32))+labs(x='13C supply (h)',y='13C product formed (nmol)',title='Lipid labeling clusters',tag='c',colour='Cluster',fill='Cluster')+theme(legend.position='bottom')
pc<-prcomp(mat,center=TRUE,scale.=FALSE);pct<-100*pc$sdev^2/sum(pc$sdev^2);pcd<-data.frame(compound=rownames(mat),PC1=-pc$x[,1]/(pc$sdev[1]*sqrt(nrow(mat))),PC2=pc$x[,2]/(pc$sdev[2]*sqrt(nrow(mat))))%>%left_join(cl,by='compound');pg<-ggplot(pcd,aes(PC1,PC2,colour=cluster))+geom_hline(yintercept=0,colour='#DFE4E8',linewidth=.25)+geom_vline(xintercept=0,colour='#DFE4E8',linewidth=.25)+geom_point(size=1.7)+geom_text_repel(aes(label=compound),seed=31,size=7/2.845276,max.overlaps=Inf,min.segment.length=0,box.padding=.55,point.padding=.2,force=2,segment.size=.2)+scale_colour_manual(values=clcols)+scale_x_continuous(expand=expansion(mult=.25))+scale_y_continuous(expand=expansion(mult=.25))+labs(x=sprintf('PC1 (%.2f%%)',pct[1]),y=sprintf('PC2 (%.2f%%)',pct[2]),title='Lipid trajectories in PCA space',tag='d',colour='Cluster')+theme(legend.position='bottom')
p<-(mp+ep+plot_layout(widths=c(1.55,1)))/(cg+pg)+plot_layout(heights=c(1.1,1))
